import { buildMediaResponseHeaders } from './buildMediaResponseHeaders.js';
import { shouldAttachMedia } from './shouldAttachMedia.js';
/**
 * After a client upload, Payload reads the file from storage to determine image dimensions.
 * For types outside the inline allowlist, such as SVG (which can contain scripts), omit
 * Content-Type so Payload uses the original upload MIME type instead of application/octet-stream.
 * Attachment and sandbox protections remain. This helper is only used when uploadReference
 * is present; normal file requests use buildMediaResponseHeaders.
 */ export function buildClientUploadFetchBackHeaders({ fallbackContentType, filename, upstreamHeaders }) {
    const effectiveContentType = upstreamHeaders.get('Content-Type') || fallbackContentType;
    const upstreamHeadersWithFallback = new Headers(upstreamHeaders);
    if (effectiveContentType) {
        upstreamHeadersWithFallback.set('Content-Type', effectiveContentType);
    }
    const headers = buildMediaResponseHeaders({
        filename,
        upstreamHeaders: upstreamHeadersWithFallback
    });
    if (effectiveContentType && shouldAttachMedia(upstreamHeadersWithFallback)) {
        // Payload uses the response content type when processing an uploaded image.
        // The sanitized type can hide the original upload MIME type.
        // Remove it so Payload falls back to the original type.
        headers.delete('Content-Type');
    }
    return headers;
}
